const group = [customerId];
const seen = new Set(group);

for (let i = 0; i < group.length; i++) {
  const customer = store.getCustomer(group[i]);
  for (const linkedId of (customer && customer.linkedAccountIds) || []) {
    if (!seen.has(linkedId)) {
      seen.add(linkedId);
      group.push(linkedId);
    }
  }
}

return group;

